#!/usr/bin/env bash
# Builds a 12 s test film with known motion and known sounds, so you can check that ear.py and eye.py
# report what is really there. Everything is generated by ffmpeg; no footage or audio from anywhere else.
#
#   0–4 s   a slow pan to the right that eases in and out
#   4 s     a hard cut
#   4–8 s   a hold (nothing moves)
#   8 s     a hard cut
#   8–12 s  a slow zoom in
#
#   1.0 s   a bell: a 1320 Hz tone that rings out
#   3.0 s   a thud: 70 Hz, gone in 100 ms
#   5.0 s   a tap: a 6 ms click of noise
#   7.0 s   a voice-like tone: 220 Hz with harmonics for half a second, faded out
#   9.0 s   a whoosh: noise that swells and fades over 0.8 s
#
# usage: make_test_clip.sh OUT.mp4
set -euo pipefail
out="${1:?usage: make_test_clip.sh OUT.mp4}"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

# Two still pictures to move over: soft coloured noise, so there is texture everywhere and no repeating pattern
# (stripes and colour bars fool any motion estimate, as they would fool your eye).
tex="format=rgb24,geq=r='random(1)*255':g='random(2)*255':b='random(3)*255',gblur=sigma=9,normalize"
ffmpeg -v error -y -f lavfi -i "nullsrc=size=1620x960:rate=1,$tex" -frames:v 1 "$tmp/a.png"
ffmpeg -v error -y -f lavfi -i "nullsrc=size=540x960:rate=1,${tex//random(/random(4+}" -frames:v 1 "$tmp/b.png"

# Shot 1: pan 0 → 1080 px over 4 s with a cosine ease (top speed 78.5 % of the width a second, halfway),
# worked out at four times the size so it moves in quarter pixels.
ffmpeg -v error -y -loop 1 -framerate 30 -t 4 -i "$tmp/a.png" \
  -vf "scale=6480:3840:flags=bicubic,crop=2160:3840:x='2160*(1-cos(PI*t/4))':y=0,scale=540:960:flags=area,format=yuv420p" \
  -r 30 "$tmp/s1.mp4"
# Shot 2: a hold.
ffmpeg -v error -y -loop 1 -framerate 30 -t 4 -i "$tmp/b.png" -vf "format=yuv420p" -r 30 "$tmp/s2.mp4"
# Shot 3: zoom 1.0 → 1.6 over 4 s (15 % a second), worked out at four times the size so it does not jitter.
ffmpeg -v error -y -loop 1 -framerate 30 -t 4 -i "$tmp/a.png" \
  -vf "crop=540:960:540:0,scale=2160:3840:flags=bicubic,zoompan=z='1+0.6*on/120':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=1:s=540x960:fps=30,format=yuv420p" \
  -frames:v 120 "$tmp/s3.mp4"

# The sound: five events on silence.
ffmpeg -v error -y -f lavfi -i "aevalsrc='\
0.4*sin(2*PI*1320*t)*exp(-5*(t-1))*gte(t,1)*lt(t,2.5)\
+0.5*sin(2*PI*70*t)*exp(-45*(t-3))*gte(t,3)*lt(t,3.3)\
+0.5*(random(0)*2-1)*gte(t,5)*lt(t,5.006)\
+0.2*(sin(2*PI*220*t)+0.5*sin(2*PI*440*t)+0.3*sin(2*PI*660*t))*min(1,(t-7)/0.02)*min(1,(7.5-t)/0.08)*gte(t,7)*lt(t,7.5)\
+0.25*(random(1)*2-1)*sin(PI*(t-9)/0.8)*gte(t,9)*lt(t,9.8)\
':s=48000:d=12" "$tmp/a.wav"

printf "file '%s'\nfile '%s'\nfile '%s'\n" "$tmp/s1.mp4" "$tmp/s2.mp4" "$tmp/s3.mp4" > "$tmp/list.txt"
ffmpeg -v error -y -f concat -safe 0 -i "$tmp/list.txt" -i "$tmp/a.wav" -c:v libx264 -crf 20 -pix_fmt yuv420p \
  -c:a aac -b:a 160k -shortest "$out"
echo "wrote $out"
